package nl.johninnl.warningprobe.route;

import android.app.Activity;
import android.app.Instrumentation;
import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.os.SystemClock;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import org.json.JSONObject;

/** Observe an app-created route only. Never construct a route, coordinator, speaker or navigation state. */
public final class MapsRouteReadinessProbe extends Instrumentation {
    private Bundle args;
    @Override public void onCreate(Bundle value){super.onCreate(value);args=value;start();}
    @Override public void onStart(){
        JSONObject result=new JSONObject();Bundle output=new Bundle();try{if(!"true".equals(args.getString("reviewed_fixture_route")))throw new IllegalArgumentException("Explicit reviewed fixture route required");result=prepareActualRoute(this,90000);}catch(Throwable error){try{result.put("status","blocked").put("error",android.util.Log.getStackTraceString(error));}catch(Exception ignored){}}
        try{result.put("probe_completed",true);}catch(Exception ignored){}output.putString("maps_route_result",result.toString());finish("observed".equals(result.optString("status"))?Activity.RESULT_OK:Activity.RESULT_CANCELED,output);
    }
    public static JSONObject prepareActualRoute(Instrumentation probe,long timeout)throws Exception{
        JSONObject result=new JSONObject();Context context=probe.getTargetContext();String pkg=context.getPackageName();if(!pkg.equals("org.ungoogled.android.apps.maps")&&!pkg.equals("com.google.android.apps.maps"))throw new IllegalArgumentException("Unexpected target");result.put("package",pkg).put("process_uid",android.os.Process.myUid()).put("process_pid",android.os.Process.myPid());Intent navigation=new Intent(Intent.ACTION_VIEW,Uri.parse("google.navigation:q=52.3791,4.9003&mode=d")).setPackage(pkg).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);context.startActivity(navigation);send(probe,"NATIVE_ROUTE_INTENT_SENT",new JSONObject().put("uri",navigation.getDataString()).put("package",pkg));ClassLoader loader=context.getClassLoader();Class<?> coordinator=loader.loadClass("org.ungoogled.ui.MapsGuidanceCoordinator"),routeType=loader.loadClass("bmia");long until=SystemClock.elapsedRealtime()+timeout;boolean ready=false;String[] last={""};
        while(SystemClock.elapsedRealtime()<until){Object reference=field(coordinator,"route").get(null),route=((java.lang.ref.WeakReference<?>)reference).get();if(route!=null){Object controller=field(routeType,"c").get(route),model=field(routeType,"e").get(route),step=field(routeType,"o").get(route);boolean active=Boolean.TRUE.equals(method(controller.getClass(),"bv").invoke(controller));result.put("route_class",route.getClass().getName()).put("controller_class",controller.getClass().getName()).put("native_navigation_active",active).put("current_route_present",model!=null).put("current_step_present",step!=null);if(active&&model!=null&&step!=null){Object path=field(model.getClass(),"b").get(model),polyline=field(path.getClass(),"k").get(path);int count=((Number)method(polyline.getClass(),"g").invoke(polyline)).intValue();result.put("native_route_model_class",model.getClass().getName()).put("native_path_class",path.getClass().getName()).put("native_polyline_class",polyline.getClass().getName()).put("native_polyline_points",count);if(count>0){java.lang.reflect.Method pointMethod=polyline.getClass().getMethod("n",int.class);Object point=pointMethod.invoke(polyline,0);result.put("first_polyline_latitude",point.getClass().getMethod("b").invoke(point)).put("first_polyline_longitude",point.getClass().getMethod("d").invoke(point));java.lang.reflect.Method snapshotMethod=coordinator.getDeclaredMethod("warningRoute",Object.class);snapshotMethod.setAccessible(true);Object snapshot=snapshotMethod.invoke(null,route);if(snapshot==null)throw new IllegalStateException("Product did not bind actual native route geometry");java.lang.reflect.Field latitudes=snapshot.getClass().getDeclaredField("latitudes"),longitudes=snapshot.getClass().getDeclaredField("longitudes");latitudes.setAccessible(true);longitudes.setAccessible(true);double[] productLatitudes=(double[])latitudes.get(snapshot),productLongitudes=(double[])longitudes.get(snapshot);if(productLatitudes.length!=count||productLatitudes[0]!=((Number)point.getClass().getMethod("b").invoke(point)).doubleValue()||productLongitudes[0]!=((Number)point.getClass().getMethod("d").invoke(point)).doubleValue())throw new IllegalStateException("Product route snapshot changed native geometry");result.put("product_directed_route_points",productLatitudes.length).put("native_geometry_snapshot_matches_product",true);}ready=true;break;}}handleOriginalSetup(probe,pkg,result,last);SystemClock.sleep(100);}
        result.put("status",ready?"observed":"inconclusive").put("actual_route_ready",ready).put("scope","Actual navigation intent and original route/controller/current-step state; no route/model/step or navigation flag created or replaced.");if(ready)send(probe,"NATIVE_ROUTE_READY",result);return result;
    }
    private static void handleOriginalSetup(Instrumentation probe,String pkg,JSONObject result,String[] lastSetup)throws Exception{
        android.view.accessibility.AccessibilityNodeInfo root=probe.getUiAutomation().getRootInActiveWindow();if(root==null||root.getPackageName()==null||!pkg.contentEquals(root.getPackageName()))return;
        java.util.List<android.view.accessibility.AccessibilityNodeInfo> nodes=new java.util.ArrayList<>();collect(root,nodes);StringBuilder text=new StringBuilder();for(android.view.accessibility.AccessibilityNodeInfo node:nodes)if(node.getText()!=null)text.append(node.getText()).append('\n');String page=text.toString(),label=page.contains("Make it your map")?"Skip":page.contains("Welcome to Google Maps navigation")?"OK":page.contains("How navigation data makes Maps better")?"Dismiss":null;
        if(label==null||page.equals(lastSetup[0]))return;for(android.view.accessibility.AccessibilityNodeInfo node:nodes)if(node.getText()!=null&&label.contentEquals(node.getText())){android.view.accessibility.AccessibilityNodeInfo click=node;while(click!=null&&!click.isClickable())click=click.getParent();if(click==null||!click.isEnabled())continue;if(click.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){lastSetup[0]=page;result.put("last_reviewed_setup_action",label);send(probe,"ORIGINAL_SETUP_CONTROL",new JSONObject().put("label",label).put("page",page));SystemClock.sleep(200);return;}}
    }
    private static void collect(android.view.accessibility.AccessibilityNodeInfo root,java.util.List<android.view.accessibility.AccessibilityNodeInfo> out){out.add(root);for(int i=0;i<root.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=root.getChild(i);if(child!=null)collect(child,out);}}
    private static void send(Instrumentation probe,String stage,JSONObject detail){Bundle out=new Bundle();out.putString("stage",stage);out.putString("detail",detail.toString());probe.sendStatus(0,out);}
    private static Field field(Class<?> owner,String name)throws Exception{for(Class<?> type=owner;type!=null;type=type.getSuperclass())try{Field value=type.getDeclaredField(name);value.setAccessible(true);return value;}catch(NoSuchFieldException absent){}throw new NoSuchFieldException(name);}
    private static Method method(Class<?> owner,String name)throws Exception{for(Class<?> type=owner;type!=null;type=type.getSuperclass())try{Method value=type.getDeclaredMethod(name);value.setAccessible(true);return value;}catch(NoSuchMethodException absent){}throw new NoSuchMethodException(name);}
}
